using System;using System.IO;using Newtonsoft.Json.Linq;using GatTelemetry;
class Program {
 static void Check(bool v,string m){if(!v)throw new Exception(m);Console.WriteLine("PASS "+m);}
 static JObject Sample()=>JObject.Parse("{'gat_profile_id':'424944555A414F','game':{'connected':true,'paused':false},'truck':{'make':'Marcopolo','model':'Paradiso G8 1600 LD','id':'modshop','licensePlate':'USV8V63','speed':0,'odometer':1000,'placement':{'x':0,'z':0}},'job':{}}");
 static int Main(string[] args){try{
  var folder=Path.Combine(Path.GetTempPath(),"bidulog-pax42-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var file=Path.Combine(folder,"journey.dat");
  var raw=Sample();var original=raw.DeepClone();var store=new PassengerJourney(file);Check(store.Current==null,"idle bus does not start a paid trip");store.Start(raw,"eduardovidal","Parauapebas","Smpara");var id=(string)store.Current["id"];
  Check(JToken.DeepEquals(raw,original),"starting monitoring preserves provider sample");Check(!File.ReadAllText(file).Contains("Parauapebas"),"persistent passenger state is protected with Windows DPAPI");
  var reopened=new PassengerJourney(file);Check((string)reopened.Current["id"]==id,"restart keeps the canonical passenger ID");Check((string)reopened.Current["origin"]=="Parauapebas","restart keeps route and confirmation");reopened.Command("finish");var again=new PassengerJourney(file);Check((string)again.Current["action"]=="finish","pending finish survives restart until server acknowledgement");
  var other=Sample();other["gat_profile_id"]="aa";again.Apply(other,"eduardovidal");Check(other["gat_passenger_session"]==null,"profile change cannot attach the previous passenger journey");
  var packet=Sample();again.Apply(packet,"eduardovidal");Check((string)packet["gat_trip_id"]==id&&(string)packet["job_latch_key"]==id,"passenger command uses one canonical signed trip ID");
  var signed=Sample();signed["gat_journal_chain"]="already-sealed";again.Apply(signed,"eduardovidal");Check(signed["gat_passenger_session"]==null,"already signed packets are never modified");
  again.Acknowledge(new JObject{["passenger_trip"]=new JObject{["id"]=id,["state"]="completed",["distance_km"]=883}});Check(again.Current==null&&new PassengerJourney(file).Current==null,"server completion is durable and clears active journey");
  var sdkFile=Path.Combine(folder,"sdk.dat");var sdk=new PassengerJourney(sdkFile);sdk.Start(raw,"eduardovidal","A","B","sdk","job-1");var sid=(string)sdk.Current["id"];sdk.Acknowledge(new JObject{["passenger_trip"]=new JObject{["id"]=sid,["state"]="completed"}});var service=new JObject{["source"]="sdk",["service_id"]="job-1",["origin"]="A",["destination"]="B"};Check(!new PassengerJourney(sdkFile).CanAutoStart(service),"completed official service cannot auto-start again after reboot");
  raw["bus_job"]=new JObject{["active"]=false};sdk.ObserveInactiveService(raw);Check(sdk.CanAutoStart(service),"a later genuine new service can start after provider becomes idle");
  foreach(var x in new[]{new[]{"Volvo","FH16","truck"},new[]{"Volvo","9700","bus"},new[]{"Scania","R 500","truck"},new[]{"Scania","Touring","bus"},new[]{"Mercedes-Benz","Actros","truck"},new[]{"Mercedes-Benz","Tourismo","bus"},new[]{"Marcopolo","Paradiso G8 1600 LD","bus"}}){var r=new JObject{["truck"]=new JObject{["make"]=x[0],["model"]=x[1]}};Check((string)VehicleClassification.Read(r)["vehicle_type"]==x[2],"catalog "+x[0]+" "+x[1]);}
  if(args.Length>0){var assembly=System.Reflection.Assembly.LoadFrom(args[0]);var type=assembly.GetType("GatTelemetry.MainForm",true);var form=System.Runtime.Serialization.FormatterServices.GetUninitializedObject(type);var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;var isolated=new PassengerJourney(Path.Combine(folder,"form.dat"));isolated.Start(Sample(),"eduardovidal","A","B");
   // Use the application's own PassengerJourney type for reflection arguments.
   var storeType=assembly.GetType("GatTelemetry.PassengerJourney",true);var appStore=Activator.CreateInstance(storeType,flags,null,new object[]{Path.Combine(folder,"app-store.dat")},null);storeType.GetMethod("Start",flags).Invoke(appStore,new object[]{Sample(),"eduardovidal","A","B","manual",""});
   type.GetField("_passengerJourney",flags).SetValue(form,appStore);type.GetField("_accountUser",flags).SetValue(form,"eduardovidal");type.GetField("_latchedJob",flags).SetValue(form,new JObject{["cargo_name"]="Frete anterior"});type.GetField("_latchedJobKey",flags).SetValue(form,"old-freight");
   var appPacket=Sample();type.GetMethod("StabilizeJobTelemetry",flags).Invoke(form,new object[]{appPacket});Check(type.GetField("_latchedJob",flags).GetValue(form)==null,"actual app does not latch the previous freight onto passengers");type.GetMethod("StampCentralTelemetry",flags).Invoke(form,new object[]{appPacket});Check(appPacket["gat_passenger_session"]!=null&&(string)appPacket["gat_trip_id"]==(string)appPacket.SelectToken("gat_passenger_session.id"),"actual app stamps passenger command before journal sealing with one trip ID");
  }
  Console.WriteLine("ALL PASSENGER CLIENT TESTS PASSED");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
